void tsk_rs_cmd_init( void )
{
    static const Cmd_Array1 cmd_array[] = 
    {            
        {INPUT_GWR_ON           , (Exec_Func)tsk_rs_cmd_gwr_on  },
        {INPUT_GWR_OFF          , (Exec_Func)tsk_rs_cmd_gwr_off },    
        {INPUT_RS_ACCESSORY_ON  , (Exec_Func)tsk_rs_cmd_acc_on  },
        {INPUT_RS_ACCESSORY_OFF , (Exec_Func)tsk_rs_cmd_acc_off },    
        {INPUT_RS_IGNITION_ON   , (Exec_Func)tsk_rs_cmd_ign_on  },
        {INPUT_RS_IGNITION_OFF  , (Exec_Func)tsk_rs_cmd_ign_off },
        {INPUT_RS_STARTER_ON    , (Exec_Func)tsk_rs_cmd_str_on  },
        {INPUT_RS_STARTER_OFF   , (Exec_Func)tsk_rs_cmd_str_off }
    };

	TRACE("\r\nTSK RS COMD INIT\r\n");

    CMD_LUT_INSERT1(cmd_array,EXEC_MODE_NORMAL);

}


